using System;
using System.Linq;
using Avalonia;
using Avalonia.Automation;
using Avalonia.Controls;
using Avalonia.Controls.Primitives;
using Avalonia.Headless;
using Avalonia.Input;
using Avalonia.Interactivity;
using Avalonia.LogicalTree;
using Avalonia.Media;
using Avalonia.VisualTree;
using static Shade.Look;

namespace Shade.Tests;

static partial class Program
{
    static void PaperFormEditor()
    {
        var a = new PaperStructure { FieldKey = "a", Label = "Child A", Background = "#112233", Bounds = new(4, 8, 20, 8) };
        var b = new PaperStructure { FieldKey = "b", Label = "Child B", Bounds = new(32, 8, 20, 8) };
        var group = new PaperStructure { Kind = "group", Title = "Container", Bounds = new(10, 10, 80, 50), Children = new[] { a, b } };
        var free = new PaperStructure { Kind = "characters", CellCount = 10, CellRanges = new[] { new PaperCellRange(0, 1, "#ABCDEF", "#654321") }, FieldKey = "free", Label = "Free field", Bounds = new(110, 80, 40, 8) };
        var builder = new PaperFormBuilder { Definition = new() { Pages = new[] { new PaperPage { Structures = new[] { group, free } } } } };
        var window = new Window { Width = 1600, Height = 1000, Content = builder }; window.Show(); Settle(); builder.Zoom = 1; Settle();
        var page = builder.GetVisualDescendants().OfType<Canvas>().Single(c => c.Width > 700);
        Point At(double x, double y) => page.TranslatePoint(new Point(x * 96 / 25.4, y * 96 / 25.4), window)!.Value;
        void Click(Point point, RawInputModifiers modifiers = RawInputModifiers.None) { window.MouseDown(point, MouseButton.Left, modifiers); window.MouseUp(point, MouseButton.Left, modifiers); Settle(); }
        Field Property(string label) => builder.GetVisualDescendants().OfType<StackPanel>().Where(p => p.Children.Count >= 2 && p.Children[0] is TextBlock t && t.Text == label).Select(p => p.Children[1]).OfType<Field>().Single();
        builder.SelectedId = group.Id; Settle(); Click(At(18, 22));
        Ok(builder.SelectedId == a.Id, "a normal canvas click selects a child inside the selected group");
        Click(At(46, 22)); Ok(builder.SelectedId == b.Id, "a canvas click selects a sibling after selecting a grouped child");
        builder.SelectedId = null; Settle();
        window.MouseDown(At(8, 16), MouseButton.Left); window.MouseMove(At(64, 28)); window.MouseUp(At(64, 28), MouseButton.Left); Settle();
        Ok(builder.SelectedIds.Count == 2 && builder.SelectedIds.Contains(a.Id) && builder.SelectedIds.Contains(b.Id), "marquee selection picks both enclosed children without selecting their enclosing group");
        builder.Values.Single(v => v.Key == "a").Text = "0024"; builder.Values.Single(v => v.Key == "b").Text = "0036";
        builder.DuplicateSelected(); Settle();
        Ok(builder.Definition.Pages[0].Structures[0].Children.Count == 4 && builder.SelectedIds.Count == 2 && builder.Values.Count(v => v.Text == "0024" || v.Text == "0036") == 4, "duplicating a multiple selection copies every field and value with new keys");
        builder.Undo(); Settle();
        window.MouseDown(At(18, 22), MouseButton.Left); window.MouseMove(At(102, 82)); window.MouseUp(At(102, 82), MouseButton.Left); Settle();
        var moved = builder.Definition.Pages[0].Structures;
        Ok(moved.Count == 4 && moved.Single(s => s.Id == group.Id).Children.Count == 0 && moved.Single(s => s.Id == a.Id).Bounds.X == 98 && moved.Single(s => s.Id == b.Id).Bounds.X == 126, "dragging a multiple selection moves children out of their group together");
        builder.Undo(); Settle(); Ok(builder.SelectedIds.Count == 2 && builder.Definition.Pages[0].Structures[0].Children.Count == 2, "undo restores multiple selection, hierarchy and geometry in one step");
        var layers = builder.GetVisualDescendants().OfType<ListBox>().Single(l => AutomationProperties.GetName(l) == "Page elements");
        ListBoxItem Row(string text) => layers.GetVisualDescendants().OfType<ListBoxItem>().Single(row => row.GetVisualDescendants().OfType<TextBlock>().Any(t => t.Text == text));
        Point RowAt(string text, double fraction = .5) { var row = Row(text); return row.TranslatePoint(new Point(50, row.Bounds.Height * fraction), window)!.Value; }
        Click(RowAt("Child A")); Click(RowAt("Child B"), RawInputModifiers.Control);
        Ok(builder.SelectedIds.Count == 2, "Ctrl-click in the native layers list selects multiple elements");
        Click(RowAt("Child B")); Click(RowAt("Child A"), RawInputModifiers.Shift);
        Ok(builder.SelectedIds.Count == 2, "Shift-click in layers selects a contiguous range");
        var drag = RowAt("Child B"); var drop = RowAt("Free field", .15);
        window.MouseDown(drag, MouseButton.Left); window.MouseMove(drag + new Vector(6, 0)); window.MouseMove(drop); Settle();
        Ok(layers.GetVisualAncestors().OfType<Panel>().First().GetVisualDescendants().OfType<Border>().Any(c => AutomationProperties.GetName(c) == "Layer insertion position" && c.IsEffectivelyVisible && c.Width > 0), "layer drag shows the insertion line at its proposed destination");
        window.MouseUp(drop, MouseButton.Left); Settle();
        moved = builder.Definition.Pages[0].Structures;
        Ok(moved.Count == 4 && moved.Single(s => s.Id == group.Id).Children.Count == 0 && moved.TakeLast(2).All(s => s.Id == a.Id || s.Id == b.Id), "dragging selected layers above a field reparents the whole selection in front of it");
        var painted = PaperFormView.LayoutPage(builder.Definition.Pages[0]);
        Ok(RowAt("Child B").Y < RowAt("Free field").Y && Array.FindIndex(painted, p => p.Structure.Id == b.Id) > Array.FindIndex(painted, p => p.Structure.Id == free.Id), "higher layer rows paint later in the drawn page");
        builder.UsePainter(false); Settle();
        var top = page.GetVisualDescendants().OfType<TextBox>().Single(t => AutomationProperties.GetName(t) == "Child B");
        var lower = page.GetVisualDescendants().OfType<TextBox>().Single(t => AutomationProperties.GetName(t) == "Free field");
        Ok(RowAt("Child B").Y < RowAt("Free field").Y && top.ZIndex > lower.ZIndex, "higher layer rows paint in front of lower rows");
        builder.UsePainter(true); Settle();
        var regroup = RowAt("Container"); drag = RowAt("Child B");
        window.MouseDown(drag, MouseButton.Left); window.MouseMove(drag + new Vector(6, 0)); window.MouseMove(regroup); window.MouseUp(regroup, MouseButton.Left); Settle();
        Ok(builder.Definition.Pages[0].Structures.Single(s => s.Id == group.Id).Children.Count == 2, "dropping in the middle of a group nests selected layers without moving their page positions");
        builder.SelectedIds = new[] { a.Id }; Settle();
        var width = Property("Width (mm)"); var increase = width.GetVisualDescendants().OfType<IconButton>().Single(i => AutomationProperties.GetName(i) == "Increase");
        Click(increase.TranslatePoint(new Point(8, 6), window)!.Value);
        Ok(builder.Definition.Pages[0].Structures.Single(s => s.Id == group.Id).Children.Single(s => s.Id == a.Id).Bounds.Width == 22, "dimension up arrow adds exactly one drawing-grid increment");
        var wheel = width.TranslatePoint(new Point(8, 8), window)!.Value; window.MouseWheel(wheel, new Vector(0, -1), RawInputModifiers.None); Settle();
        Ok(builder.Definition.Pages[0].Structures.Single(s => s.Id == group.Id).Children.Single(s => s.Id == a.Id).Bounds.Width == 20, "wheel over a dimension changes its value by the drawing-grid increment");
        width.Box.Focus(); window.KeyPress(Key.Up, RawInputModifiers.None, PhysicalKey.None, null); window.KeyRelease(Key.Up, RawInputModifiers.None, PhysicalKey.None, null); Settle();
        Ok(builder.Definition.Pages[0].Structures.Single(s => s.Id == group.Id).Children.Single(s => s.Id == a.Id).Bounds.Width == 22, "dimension fields accept keyboard up/down increments");
        var grid = Property("Grid pitch (mm)"); Ok(grid.IsEffectivelyVisible, "grid settings remain visible while an element is selected");
        builder.InspectorPlacement = PaperInspectorPlacement.Ribbon; Settle();
        Ok(Property("Width (mm)").TranslatePoint(default, window)!.Value.Y < page.TranslatePoint(default, window)!.Value.Y && Property("Grid pitch (mm)").IsEffectivelyVisible, "apps can place properties in a top ribbon while keeping the grid ribbon visible");
        builder.InspectorPlacement = PaperInspectorPlacement.Sidebar; Settle();
        var fonts = builder.GetVisualDescendants().OfType<SearchChoice>().Single();
        fonts.ItemsSource = Enumerable.Range(0, 800).Select(i => $"Family {i:000}").ToArray(); fonts.SelectedItem = "Family 650";
        fonts.BringIntoView(); Settle(); fonts.IsDropDownOpen = true; Settle();
        var fontPopup = fonts.GetVisualDescendants().OfType<Popup>().Single();
        var fontRow = fontPopup.Child!.GetVisualDescendants().OfType<Button>().First(c => c.Content is string name && name != "Family 650" && c.TranslatePoint(new Point(4, c.Bounds.Height / 2), fontPopup.Child!) is { } p && p.Y > 50 && p.Y < fontPopup.Child!.Bounds.Height - 4);
        string chosenFont = (string)fontRow.Content!;
        var fontText = fontRow.GetVisualDescendants().OfType<TextBlock>().First(); var fontRoot = TopLevel.GetTopLevel(fontText)!;
        var fontPoint = fontText.TranslatePoint(new Point(4, fontText.Bounds.Height / 2), fontRoot)!.Value;
        fontRoot.MouseDown(fontPoint, MouseButton.Left); fontRoot.MouseUp(fontPoint, MouseButton.Left); Settle();
        Ok(builder.Definition.Pages[0].Structures.Single(s => s.Id == group.Id).Children.Single(s => s.Id == a.Id).FontFamily == chosenFont && !fonts.IsDropDownOpen, "clicking font-name text in a scrolled virtualized picker applies it to the paper field");

        var colour = builder.GetVisualDescendants().OfType<ActionButton>().Single(c => AutomationProperties.GetName(c) == "Text colour");
        colour.BringIntoView(); Settle(); colour.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Settle();
        var popup = (window.FocusManager!.GetFocusedElement() as Control)!.GetLogicalAncestors().OfType<Popup>().Single(p => p.IsOpen);
        var hex = popup.Child!.GetVisualDescendants().OfType<TextBox>().Single(t => AutomationProperties.GetName(t) == "Hex colour");
        Ok(Color.TryParse("#" + hex.Text, out _), "colour helper initially displays the resolved hex colour even when the field uses Default");
        var reset = popup.Child!.GetVisualDescendants().OfType<ActionButton>().Single(c => c.Content?.ToString() == "Default");
        Ok(reset.TranslatePoint(default, popup.Child!)!.Value.Y < hex.TranslatePoint(default, popup.Child!)!.Value.Y && hex.GetVisualAncestors().OfType<ColorGrid>().Any(), "the hex value is typed in the colour grid's own footer; Default sits in the header row");
        var palette = popup.Child!.GetVisualDescendants().OfType<ColorGrid>().Single();
        Ok(palette.IsDocumentPalette && !new ColorGrid().IsDocumentPalette, "paper colour helpers opt out of theme accents without changing theme picker defaults");
        Ok(popup.Child!.GetVisualDescendants().OfType<ActionButton>().Any(c => AutomationProperties.GetName(c) == "Use #112233") && popup.Child!.GetVisualDescendants().OfType<ActionButton>().Any(c => AutomationProperties.GetName(c) == "Use #ABCDEF"), "form colours include nested field fills and character-cell range colours");
        var used = popup.Child!.GetVisualDescendants().OfType<ActionButton>().Single(c => AutomationProperties.GetName(c) == "Use #112233");
        used.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Settle();
        Ok(hex.Text == "112233" && palette.Value == Color.Parse("#112233"), "a form-colour swatch updates the hex field and palette preview");
        var paletteRoot = TopLevel.GetTopLevel(palette)!; var swatch = palette.TranslatePoint(new Point(40, 50), paletteRoot)!.Value;
        paletteRoot.MouseDown(swatch, MouseButton.Left); paletteRoot.MouseUp(swatch, MouseButton.Left); Settle();
        Ok(popup.IsOpen && hex.Text != "112233" && "#" + hex.Text == HexOf(palette.Value), "clicking a palette colour fills the hex field and leaves it visible");
        hex.Focus(); hex.SelectAll(); window.KeyTextInput("#80123456"); Settle();
        Ok(builder.Definition.Pages[0].Structures.Single(s => s.Id == group.Id).Children.Single(s => s.Id == a.Id).Foreground == "#80123456" && palette.Value.A == 128, "hex editing preserves alpha and refreshes the palette preview");
        Click(colour.TranslatePoint(new Point(8, 8), window)!.Value);
        Ok(!popup.IsOpen, "clicking an open colour selector again closes its helper");
        var fill = builder.GetVisualDescendants().OfType<ActionButton>().Single(c => AutomationProperties.GetName(c) == "Fill colour"); fill.BringIntoView(); Settle(); fill.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Settle();
        var fillPopup = (window.FocusManager.GetFocusedElement() as Control)!.GetLogicalAncestors().OfType<Popup>().Single(p => p.IsOpen);
        var recent = fillPopup.Child!.GetVisualDescendants().OfType<ScrollViewer>().Single(c => AutomationProperties.GetName(c) == "Recent colours");
        recent.GetVisualDescendants().OfType<ActionButton>().Single(c => AutomationProperties.GetName(c) == "Use #80123456").RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Settle();
        Ok(builder.Definition.Pages[0].Structures.Single(s => s.Id == group.Id).Children.Single(s => s.Id == a.Id).Background == "#80123456", "recent document colours are shared across text and fill and preserve alpha");
        fillPopup.IsOpen = false; builder.Definition = builder.Definition with { Landscape = true }; Settle();
        var border = builder.GetVisualDescendants().OfType<ActionButton>().Single(c => AutomationProperties.GetName(c) == "Border colour"); border.BringIntoView(); Settle(); border.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); Settle();
        var freshPopup = (window.FocusManager.GetFocusedElement() as Control)!.GetLogicalAncestors().OfType<Popup>().Single(p => p.IsOpen);
        Ok(!freshPopup.Child!.GetVisualDescendants().OfType<ScrollViewer>().Any(c => AutomationProperties.GetName(c) == "Recent colours"), "replacing the document clears its recent-colour history"); freshPopup.IsOpen = false;
        window.Close();

        var characters = new PaperStructure { Kind = "characters", FieldKey = "reading", CellCount = 4, CellWidth = 4, Bounds = new(12, 12, 40, 8), GridAlignment = TextAlignment.Right, Alignment = TextAlignment.Left };
        var date = new PaperStructure { Kind = "date", FieldKey = "date", Bounds = new(12, 30, 50, 8), DateFormat = "dd.MM.yyyy" };
        var form = new PaperFormBuilder { Definition = new() { ShowPageNumbers = true, Pages = new[] { new PaperPage { Structures = new[] { characters, date } }, new PaperPage() } }, SideBySidePages = true };
        var host = new Window { Width = 1600, Height = 1000, Content = form }; host.Show(); Settle(); form.FitTwoPages(); Settle();
        var pages = form.GetVisualDescendants().OfType<Canvas>().Where(c => c.Width > 700).ToArray();
        var first = pages[0].TranslatePoint(default, host)!.Value; var second = pages[1].TranslatePoint(default, host)!.Value;
        Ok(Math.Abs(first.Y - second.Y) < 1 && second.X > first.X + 100, "two-page layout places consecutive sheets side by side inside the canvas");
        form.Mode = PaperFormMode.Fill; Settle();
        var cells = Editor<CharacterGridField>(form, characters.Id);
        double inset = cells.TranslatePoint(default, pages[0])!.Value.X / (96 / 25.4);
        Ok(Math.Abs(inset - 36) < .5 && cells.CharacterAlignment == TextAlignment.Left && Math.Abs(cells.Width - 16 * 96 / 25.4) < 1, "whole-grid right alignment keeps complete cells at the right edge independently of glyph alignment");
        Ok(form.Definition.PageNumberText(1, 2) == "Page 1 of 2" && form.ExportHtml().Contains("Page 1 of 2") && form.ExportHtml().Contains("Page 2 of 2"), "optional page numbering is exported inside each printed page footer (the drawn page's pixels are covered by the painter comparisons)");
        form.Values.Single(v => v.Key == "date").Text = "31.02.2026"; Settle(); form.RefreshProblems();
        Ok(form.Problems.Any(p => p.StructureId == date.Id), "date field keeps an invalid date draft and reports the configured format");
        form.Values.Single(v => v.Key == "date").Text = "29.02.2028"; Settle(); form.RefreshProblems();
        Ok(form.Problems.Count == 0, "date format validation accepts a real leap day");
        string html = form.ExportHtml();
        Ok(html.Contains("data-date-format=\"dd.MM.yyyy\"") && html.Contains("character-container") && html.Contains("Page 1 of 2"), "editable HTML preserves date format, whole-grid alignment and printed page numbering");
        form.ShowPageNavigation = false; Settle();
        Ok(!form.GetVisualDescendants().OfType<IconButton>().Single(c => AutomationProperties.GetName(c) == "Next page").IsEffectivelyVisible, "apps can hide footer page navigation independently of printed page numbering");
        host.Close();
    }
}
